for q in qs:
 q['translationReview']={'method':'EN/FR comparison by Codex; no external translator','promptAndOptionsChecked':True,'explanationChecked':q['translationStatus']=='validated','expertCertification':False}
(root/'data/questions.json').write_text(json.dumps(qs,ensure_ascii=False,indent=2))
